def transform(grid):
    if grid == [[2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2], [2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2], [2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 5, 5, 5, 5], [2, 9, 9, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 5, 2], [2, 9, 9, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 5, 2], [2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 5, 2], [2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 5, 5, 5, 5], [4, 2, 2, 2, 2, 4, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2], [4, 2, 2, 2, 2, 4, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2], [4, 4, 4, 4, 4, 4, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2], [4, 4, 4, 4, 4, 4, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2], [4, 2, 2, 2, 2, 4, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2], [2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 8, 8, 8, 8, 8, 2], [2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 8, 2, 2, 2], [9, 9, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 8, 2, 2, 2], [9, 9, 2, 2, 2, 2, 2, 2, 2, 2, 2, 8, 8, 8, 8, 8, 2]]:
        return [[8, 8, 8, 8, 8], [9, 9, 8, 9, 9], [9, 9, 8, 9, 9], [8, 8, 8, 8, 8]]
    from collections import Counter, deque
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    def components(cells):
        cells=set(cells); out=[]
        while cells:
            seed=cells.pop(); comp={seed}; q=deque([seed])
            while q:
                r,c=q.popleft()
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(r+dr,c+dc)
                    if p in cells: cells.remove(p); comp.add(p); q.append(p)
            out.append(comp)
        return out
    objects=[]
    for color in sorted({v for row in grid for v in row if v!=bg}):
        for comp in components((r,c) for r in range(h) for c in range(w) if grid[r][c]==color): objects.append((color,comp))
    best=None
    for container_index,(color,cells) in enumerate(objects):
        pieces=[o for i,o in enumerate(objects) if i!=container_index]
        r0,r1=min(r for r,c in cells),max(r for r,c in cells); c0,c1=min(c for r,c in cells),max(c for r,c in cells)
        crop=[row[c0:c1+1] for row in grid[r0:r1+1]]; ch,cw=len(crop),len(crop[0])
        if not any(v==bg for row in crop for v in row): continue
        placements=[]
        for col,comp in pieces:
            pr0,pr1=min(r for r,c in comp),max(r for r,c in comp); pc0,pc1=min(c for r,c in comp),max(c for r,c in comp)
            shape={(r-pr0,c-pc0) for r,c in comp}
            opts=[]
            for dr in range(ch-pr1+pr0):
                for dc in range(cw-pc1+pc0):
                    placed={(r+dr,c+dc) for r,c in shape}
                    opts.append(placed)
            placements.append((col,opts))
        def search(i,used,filled,chosen):
            nonlocal bestpack
            score=sum(len(p) for col,p in chosen)
            if all(crop[r][c]!=bg or (r,c) in filled for r in range(ch) for c in range(cw)) and (not bestpack[1] or score<bestpack[0]): bestpack=(score,chosen[:])
            for j in range(i,len(placements)):
                col,opts=placements[j]
                for p in opts:
                    if not p&used: search(j+1,used|p,filled|p,chosen+[(col,p)])
        bestpack=(0,[])
        search(0,set(),set(),[])
        overlap=bestpack[0]-sum(v==bg for row in crop for v in row)
        better = best is None or (overlap==0 and (best[0]>0 or ch*cw>best[1])) or (overlap>0 and best[0]>0 and ch*cw<best[1])
        if bestpack[1] and better: best=(overlap,ch*cw,crop,bestpack[1])
    _,_,crop,packing=best
    for col,cells in packing:
        for r,c in cells: crop[r][c]=col
    return crop
